"""Stance and evaluation detector for layers.15.mlp.down_proj component 5632.

What it is: this component is mostly one MLP hidden unit of layer 15 (unit 5632), read
through its input direction. It goes negative where the text is about to comment on a
statement: a reaction word opening a reply ("Hmm", "Wait", "Yes"), a sentence-initial
"This" / "That" that refers back to what was just said, the verb after such a subject
("This is", "which is", "that's"), a "fact / case / thing / problem" noun that sets up a
judgement, an evaluative predicate ("possible", "important", "makes sense"), and in
Japanese or Korean the nominalisers that introduce a clause ("ということ", "のは", "것").
Most other tokens sit near zero, with a small positive drift on ordinary words.

What this program does: each token gets the value of the first class it belongs to, from
the word lists below, and 0 otherwise. The values are least-squares fits to the component's
activation on training text. It explains only a small share of the variance: the component
also depends on context that a word list cannot see, and a word-list model of any size
reaches only about 2-3% on held-out text.
"""

READS = ()

INTERJECTIONS = {"hmm", "wait", "yes", "yeah", "okay", "oh"}
EVALUATIVE = {"possible", "impossible", "important", "interesting", "consistent", "makes",
              "thing", "problematic", "something", "difficult", "helpful"}
FACT_NOUNS = {"fact", "case", "problem", "issue", "matter"}
NOMINALIZERS = {"こと", "のは", "のが", "のも", "ということ", "ことが", "ことは", "ことも", "ことに", "것", "のです"}
CONTRASTIVES = {"but", "however", "no", "because"}
DEMONSTRATIVES = {"this", "that", "which", "it", "what"}
COPULAS = {"is", "'s", "’s", "be", "was", "can", "would", "will", "are", "has", "makes"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    raw = prefix.token_strings[-1].strip()
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    before = prefix.token_strings[-2].strip().lower() if same_doc else ""
    if word in INTERJECTIONS:
        return carry, -2.0
    if raw in ("This", "That"):
        return carry, -1.4
    if before in DEMONSTRATIVES and word in COPULAS:
        return carry, -0.8
    if word in NOMINALIZERS:
        return carry, -5.8
    if word in EVALUATIVE:
        return carry, -1.2
    if word in FACT_NOUNS:
        return carry, -0.6
    if word in CONTRASTIVES:
        return carry, -0.4
    if word == "this":
        return carry, -0.6
    return carry, 0.0

"""Component 5635 of layers.15.mlp.down_proj, as a rough word-level guess.

The component is almost one MLP hidden unit: about 60% of its input direction sits on
hidden unit 5635 of layer 15, and its output is that unit's value times the output norm.
That unit is mostly near zero, but fires strongly in technical text and code, and it is
strongly negative in knowledge-base lists such as "X -> instance of -> Y".

Token identity explains little of its value, so this program predicts only the broad
trends, from the current token and the two before it in the same document:
  - " of" right after " instance" is strongly negative (about -3.5);
  - verbs of what a tool or function can do (allow, create, add, write, support, run,
    use, make, ...) and "multiple"/"complex" are mildly positive;
  - code keywords (void, def, fn, public, static, func) are positive;
  - "to", "can", "for", "be", "a", "an", "with" are weakly positive, more so after a
    capability word (ability, able, tool, use, allow, support, user, how, you, can,
    want, need);
  - whitespace-only tokens (indentation) are slightly positive.
Everything else sits at a small baseline.
"""

READS = ()

VERBS = {"allow", "allows", "create", "add", "write", "support", "run", "multiple",
         "complex", "want", "use", "make", "connect", "post"}
CODE = {"void", "def", "fn", "public", "static", "func"}
LINK = {"to", "can", "for", "be", "a", "an", "with"}
CAPABILITY = {"ability", "able", "tool", "use", "used", "allow", "allows", "allowing",
              "support", "user", "users", "how", "you", "can", "want", "need"}


def _word(s):
    return s.strip().lower()


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = _word(toks[-1])
    same = prefix.document_ids
    prev = _word(toks[-2]) if len(toks) > 1 and same[-2] == same[-1] else ""
    prev2 = _word(toks[-3]) if len(toks) > 2 and same[-3] == same[-1] else ""
    if prev == "instance" and cur == "of":
        return carry, -3.5
    value = 0.03
    if toks[-1].strip() == "" and toks[-1] != "":
        value += 0.1
    if cur in VERBS:
        value += 0.45
    if cur in CODE:
        value += 0.6
    if cur in LINK:
        value += 0.15
        if prev in CAPABILITY or prev2 in CAPABILITY:
            value += 0.3
    return carry, value

"""Weak lexical tendencies of one MLP component in Qwen3-1.7B layer 15.

The component's activation (std 0.30, mean 0) is a diffuse, context-dependent
readout of the MLP hidden state. Almost none of it is explained by the current
token. These are the strongest token-level tendencies found on 16k training rows,
written at the small size the data supports:

- plural/sentence-subject demonstratives ("These", "Those", "这些", "Это") lean positive;
- Japanese quotative and nominalizer endings ("という", "いう", "こと", "のは", "です")
  and filler words ("Hmm", "Okay", "'m") lean negative;
- closing code/markdown delimiters ("}", "):", "`") lean slightly positive.

Each prediction is a small fixed value, so the program explains about 0.1% of
the variance: it is a sketch of the tendencies, not a model of the component.
"""

READS = ()

DEMONSTRATIVE_SUBJECTS = {"These", "Those", "这些", "Это", "其中", "which", "Both"}
JAPANESE_QUOTATIVE_NOMINALIZER = {"という", "いう", "ということ", "こと", "のは", "のです", "ことが", "のか", "です", "します", "する", "って"}
FILLERS = {"Hmm", "Okay", "’m", "'m"}
CLOSERS = {"}", "};", "});", "):", "`", "]", '"}}', "```"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    if token in DEMONSTRATIVE_SUBJECTS:
        value = 0.15
    elif token in JAPANESE_QUOTATIVE_NOMINALIZER or token in FILLERS:
        value = -0.15
    elif token in CLOSERS:
        value = 0.08
    else:
        value = 0.0
    return carry, value

"""Fires on the words that set up a bare verb: modal auxiliaries (can, must, will ...),
the infinitive "to" (want to, able to), and "not"/"never" after do/can. Weaker on subject
pronouns and relative "who", negative on "be"/"was" and sentence connectives."""
from collections.abc import Mapping

READS: tuple[str, ...] = ()

MODALS = {"can", "could", "may", "might", "must", "shall", "should", "will", "would", "cannot",
          "'ll", "’ll", "'d", "’d", "可以", "能", "会", "要", "不能", "不会", "必须", "可能",
          "могут", "может", "peut"}
DO_AUX = {"do", "does", "did", "don", "doesn", "didn", "won", "couldn", "wouldn", "shouldn",
          "can", "could", "would", "will", "should", "must", "may", "might", "cannot"}
# words after which "to" is a preposition ("due to", "back to"), not an infinitive marker
PREP_TO = {"due", "according", "related", "back", "compared", "similar", "access", "respect",
           "addition", "connected", "prior", "close", "equal", "subject", "relative", "lead",
           "leads", "leading", "referred", "response", "up", "down", "out", "on", "applied",
           "added", "available", "approach", "contrast", "proportional", "parallel"}
# subjects and relatives, which are often followed by a verb
SUBJECTS = {"they", "he", "she", "we", "you", "i", "it", "who", "that", "which"}
# adverbs that often sit between a subject and its verb
ADVERBS = {"also", "just", "still", "already", "only", "never", "not", "ever", "until"}
BE = {"be", "was", "is", "are", "were", "been", "being", "am"}
CONNECTIVES = {"however", "after", "furthermore", "additionally", "moreover", "instead"}


def step(carry, prefix, upstream: Mapping):
    word = prefix.token_strings[-1].strip().lower()
    prev = ""
    if len(prefix.token_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2].strip().lower()
    if word in MODALS:
        return carry, 2.0
    if word in ("'t", "’t") and prev in DO_AUX:
        return carry, 1.9
    if word == "to":
        return carry, 0.0 if prev in PREP_TO else 1.15
    if word in ("not", "never") and prev in DO_AUX:
        return carry, 2.2
    if word == "who":
        return carry, 1.8
    if word in SUBJECTS or word in ADVERBS:
        return carry, 0.5
    if word in BE or word in CONNECTIVES:
        return carry, -0.3
    return carry, 0.0

"""Indefinite-article detector for layers.15.mlp.down_proj component 5642.

The component fires on an indefinite determiner that opens a noun phrase: "a", "an" and
their counterparts in other languages ("un", "une", "ein", "uma", ...), plus "some", "any",
"another", "certain", "various". Its size depends on the word just before it:

- after a preposition, strongly (about 3-4.5): "on a", "by an", "through a", "in some";
- after a copula or "as" ("is a", "was an", "as a"), weakly (about 1);
- after anything else, moderately (about 1.6): "and a", "have a", ", a".

Every other token gets 0. The program ignores the rest of the variance (most of it is small,
token-specific noise on ordinary tokens), so it explains about an eighth of the variance.
"""
from collections.abc import Mapping

READS: tuple[str, ...] = ()

INDEFINITE = {
    " a", " an", " some", " any", " another", " certain", " various", " several",
    " un", " une", " ein", " einer", " eine", " uma", " una", " um", " bir", " algum",
}
PLACE_PREPOSITIONS = {" on", " by", " through", " within", " to", " in", " from", " during", " into"}
OTHER_PREPOSITIONS = {
    " at", " for", " of", " with", " using", " under", " over", " about", " dans", " para", " par",
    " por", " auf",
}
COPULAS = {" is", " was", " be", " are", " as", " been", " not", " were", "'s", " being"}


def step(carry, prefix, upstream: Mapping):
    cur = prefix.token_strings[-1]
    if cur not in INDEFINITE:
        return carry, 0.0
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if prev in PLACE_PREPOSITIONS:
        return carry, 4.3
    if prev in OTHER_PREPOSITIONS:
        return carry, 3.0
    if prev in COPULAS:
        return carry, 1.0
    return carry, 1.6

"""Layer 15 MLP down_proj, component 5650, as a word-class rule.

The component is mostly the layer-15 MLP hidden unit 5650 (about half of its covariance
with the activation; the rest is spread thinly over thousands of units). It is positive on
words that attach a modifier to the noun just before them, and negative on copulas and on
generic people/thing words. Written as plain rules:

  * a relative pronoun (that, which, who, qui, que, ...) right after a noun:  +0.3
  * the same pronoun elsewhere:  +0.14
  * a past participle (obtained, made, held, generated, ...) right after a noun:  +0.16
  * a past participle elsewhere:  +0.06
  * a copula or auxiliary (is, are, be, was, 're, ...):  -0.1
  * an indefinite or generic people word (everyone, everything, person, women, ...):  -0.15
  * everything else:  0

Each value is the least-squares fit of the activation on these classes, so the program
predicts the component's average level for each class. It explains only a sliver of the
variance: the activation is diffuse, with most of its size in moderate values on tokens
that no word list picks out.
"""

import wordnet

READS = ()

RELATIVE = {"that", "which", "who", "whom", "whose", "qui", "que", "welche", "которая", "которые", "который", "które", "che"}
INDEFINITE = {"everyone", "everything", "someone", "something", "anyone", "anything", "nobody", "everybody",
              "person", "people", "women", "men"}
COPULA = {"is", "are", "be", "was", "were", "been", "being", "am", "'re", "'m", "’re"}
IRREGULAR = {"made", "given", "taken", "known", "shown", "found", "held", "built", "written", "spent", "sent",
             "paid", "sold", "brought", "bought", "done", "seen", "born", "chosen", "driven", "caused"}


def is_noun(word):
    return word.isalpha() and "noun" in wordnet.parts_of_speech(word)


def is_participle(word):
    if word in IRREGULAR:
        return True
    return word.isalpha() and word.endswith("ed") and "verb" in wordnet.parts_of_speech(word)


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2].strip().lower() if same_doc else ""
    after_noun = bool(prev) and is_noun(prev)
    if word in RELATIVE:
        value = 0.3 if after_noun else 0.14
    elif is_participle(word):
        value = 0.16 if after_noun else 0.06
    elif word in COPULA:
        value = -0.1
    elif word in INDEFINITE:
        value = -0.15
    else:
        value = 0.0
    return carry, float(value)

"""Alias and gloss introducers: a weak, diffuse layer-15 MLP feature.

Component p-82af68dd@100000/layers.15.mlp.down_proj:5657 writes a small amount into the
residual stream. Its activation is mostly low-level, token-specific noise (about +-0.3). Its
large values (mostly 2 to 10) come where the text is about to give another name, an
equivalent or an approximation for what was just said:

  "also known [as]", "commonly known [as]", "the common [name]", "commonly [called]",
  "km [(]" (a unit followed by its equivalent), "[about]", "[approximately]", "[≈]".

This program predicts those positions with a fixed value and 0 elsewhere. It captures only
a tiny share of the variance, because the large values are rare and the rest is not
explained by any simple word rule.
"""

ALIAS_VERBS = {"known", "called", "referred", "termed", "named", "dubbed"}
ADVERBS = {"commonly", "also", "better", "often", "popularly", "widely", "generally",
           "colloquially", "simply", "usually", "locally", "sometimes"}
UNITS = {"km", "kilometres", "kilometers", "miles", "mile", "meters", "metres", "feet",
         "degrees", "kg", "pounds", "inches", "cm", "mm", "mg", "ml", "ft", "lb", "%",
         "hours", "days", "years", "percent"}
APPROX = {"≈", "approximately", "about", "approx", "roughly", "around", "namely", "aka"}
OPENERS = {"(", "“", '"', "‘", "'"}

READS = ()


def word(text):
    return text.strip().lower()


def step(carry, prefix, upstream):
    t = prefix.position
    doc = prefix.document_ids

    def back(k):
        # the token k steps back, if it is in the same document
        i = t - k
        if i < 0 or doc[i] != doc[t]:
            return ""
        return word(prefix.token_strings[i])

    cur = word(prefix.token_strings[t])
    prev1 = back(1)

    value = 0.0
    if cur == "as" and prev1 in ALIAS_VERBS:
        value = 0.9
    elif cur in ALIAS_VERBS and prev1 in ADVERBS:
        value = 1.0
    elif cur in ("name", "names") and prev1 == "common":
        value = 4.0
    elif cur in OPENERS and prev1 in UNITS:
        value = 0.6
    elif cur in APPROX:
        value = 0.1
    return carry, float(value)

"""Component 5677 of layers.15.mlp.down_proj: the "as well as" / "in addition" connective.

It fires on the words that add one thing to another, or set two things side by side:
  * "as well as": the "well" (about 28) and the "as" after it (about 15), and the "as"
    after a comma that starts an additive clause (", as well as", ", as it ...") (about 13);
  * additive and alternative connectives: "besides", "in addition", "along/together with"
    (the "with" after them is about 10), "plus", "including", "also", "or", "nor", "both";
  * the "+" operator (about 5, more after a letter), and "-" (about 2);
  * the same words in other languages: "ainsi que", "sowie", "además", "также", "como".
Comparative and role uses of "as" stay near zero: "not as", "is as", "such as", "known as".
Sentence linkers ("however", "therefore") and plain "and" stay near zero too.

The values are typical activations in the component's own units, read off a sample of
training text; the program is a lookup of words plus the context of the previous word.
"""

READS = ()

# Additive, alternative and other connectives that join one thing to another.
ADDITIVE = {
    " besides": 9.0, " Besides": 9.0,
    " addition": 8.0, " additionally": 6.5, " Additionally": 6.5,
    " along": 4.5, " Along": 6.5, " alongside": 4.5, " together": 2.5, " Together": 5.0,
    " including": 6.0, " Including": 5.5, " plus": 3.7, " Plus": 4.6,
    " also": 2.5, " Also": 4.5, " both": 3.5, " Both": 3.5,
    " or": 3.0, " OR": 2.5, " either": 2.5, " nor": 5.5, " neither": 5.0,
    " instead": 3.7, " rather": 3.6, " opposed": 4.0, " compared": 2.1, " too": 1.0,
    " because": 4.0, " since": 3.7, " Since": 2.5, " while": 3.9, " whereas": 4.0,
    " though": 2.5, " even": 2.3,
    " and": -0.4,
}

# The same idea in other languages ("as well as", "also", "as", "or").
OTHER_LANGUAGES = {
    " ainsi": 13.0, " sowie": 16.0, " además": 14.0, " también": 3.4,
    " также": 9.7, " как": 5.4, " como": 6.0, " comme": 6.7, " als": 4.0, " wie": 4.4,
    " anche": 5.4, " oraz": 7.8, " jak": 5.2, " или": 2.9, " ou": 3.2, " oder": 2.5,
    " 以及": 9.2,
}

PLUS = {" +", "+", ")+"}
MINUS = {" -", " −", "−"}
AS_TOKENS = (" as", "As", " As")
# "as" after these is a comparison ("not as easy as") or a role ("known as"): near zero.
COPULA = {" not", " is", " be", " are", " was", " isn", " aren"}
ROLE_AS = {" such", "such", " known", " same", " defined", " described", " regarded",
           " considered", " seen", " treated", " served", " expressed", " used", " represented"}
SENTENCE_END = {".", "\n", "?", "!", ";", ":"}


def clause_words_before(token_strings):
    """Words since the last sentence break, before the comma that precedes the current token."""
    words = 0
    for s in reversed(token_strings):
        if s in SENTENCE_END:
            break
        words += 1
    return words


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    same = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2] if same else ""
    if tok in AS_TOKENS:
        if prev == " well":
            return carry, 14.5
        if prev == ",":
            # ", as" after a full clause starts an additive phrase; after a short opener
            # ("However, as") it is weak
            return carry, 13.0 if clause_words_before(prefix.token_strings[:-2]) >= 2 else 4.0
        if prev in COPULA:
            return carry, -2.0
        if prev in ROLE_AS:
            return carry, 1.0
        return carry, 3.0
    if tok == " well":
        return carry, 28.0 if prev == " as" else 1.0
    if tok == " with":
        return carry, 10.0 if prev in (" along", " together") else 0.0
    if tok in PLUS:
        return carry, 5.0
    if tok in MINUS:
        return carry, 2.0
    if tok in OTHER_LANGUAGES:
        return carry, OTHER_LANGUAGES[tok]
    return carry, ADDITIVE.get(tok, 0.0)

"""Layer 15, MLP neuron 5681 of Qwen3-1.7B. The component is this hidden unit's down-projection
column (about three quarters of its direction is unit 5681 itself), so its activation is the
unit's value, silu(gate) * up, times the column's norm.

The gate pre-activation is usually negative (open, above 1, on about 1% of positions), so the
value is mostly small, and when the gate opens its sign follows the "up" readout, a dense,
context-dependent mix of the residual stream. Strongest negative values come on the head noun
of a technical noun compound ("quaternions [theory]", "sector", "list", "array"), but such
word classes shift the mean only slightly. No simple word or token rule predicts it well; the
readable structure is mainly positional, so this program uses that:

- the first token of a document: about zero;
- the second token: depends on what the first token was (a plural noun or a digit pushes it
  strongly negative, a symbol or a space pushes it positive);
- tokens 3 to 8 of a document: a negative offset that fades with distance from the start;
- everything later: a small constant negative level, the neuron's typical value.

Document positions restart at each document, as in the model. The carry holds the current
document label and the position within it.
"""

import re

import wordnet

READS = ()

LATE = -0.05
FIRST = -0.02
EARLY = {2: -0.33, 3: -0.26, 4: -0.20, 5: -0.15, 6: -0.12, 7: -0.10}
SECOND = {"space": 0.2, "symbol": 0.8, "digit": -1.4, "plural": -3.3, "word": -0.1, "other": -0.3}


def token_class(text):
    """A coarse class of the first token of a document, from its text alone."""
    word = text.strip()
    if not word:
        return "space"
    if re.fullmatch(r"\d+", word):
        return "digit"
    if re.fullmatch(r"[A-Za-z]+", word):
        lower = word.lower()
        if len(lower) > 3 and lower.endswith("s") and "noun" in wordnet.parts_of_speech(lower):
            return "plural"
        return "word"
    if re.fullmatch(r"[^\w\s]+", word):
        return "symbol"
    return "other"


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        index = 0
    else:
        index = carry[1] + 1
    carry = (document, index)
    if index == 0:
        value = FIRST
    elif index == 1:
        value = SECOND[token_class(prefix.token_strings[-2])]
    else:
        value = EARLY.get(index, LATE)
    return carry, float(value)

"""Negative dips near the start of a document, on sentence-opening subject pronouns,
indentation and code punctuation.

This unit's activation is mostly small noise around 0.05 (std ~0.55), with a heavy
negative tail. The tail is concentrated near the start of a document: the first few
dozen tokens. There the unit dips negative on
  - a subject pronoun that opens a sentence (" He", " She", " It", " They", lowercase too):
    strongly, within the first 40 tokens of a document; weakly after that;
  - pure indentation (spaces or tabs, no newline) in the first 40 tokens;
  - code punctuation ({ } ; # * / @, ".h") in the first 40 tokens.
Everything else sits at the typical value 0.05.
"""

READS = ()

TYPICAL = 0.05
PRONOUNS = {"he", "she", "it", "they"}
SENTENCE_ENDS = {".", "?", "!", '."', ")."}
EARLY = 40  # tokens into a document where the near-start effect is strongest
CODE_MARKS = set("{};#*/@")


def is_code(core):
    return any(ch in CODE_MARKS for ch in core) or core.endswith(".h")


def step(carry, prefix, upstream):
    t = prefix.position
    new_doc = t == 0 or prefix.document_ids[t] != prefix.document_ids[t - 1]
    start = t if new_doc else carry
    depth = t - start  # position in the document
    token = prefix.token_strings[t]
    core = token.strip()
    previous = prefix.token_strings[t - 1].strip() if t > 0 else ""
    value = TYPICAL
    if new_doc:
        value = 0.0  # a document's first token is near zero
    elif core.lower() in PRONOUNS and token.startswith(" ") and previous in SENTENCE_ENDS:
        value = -2.2 if depth < EARLY else -0.5
    elif core.lower() in PRONOUNS and token.startswith(" ") and depth < EARLY:
        value = -0.7
    elif core == "" and "\n" not in token and depth < EARLY:
        value = -0.9 if depth < 8 else -0.2
    elif core and is_code(core) and depth < EARLY:
        value = -0.4 if depth < 8 else -0.15
    return start, value
